/*==========================================================================*/

Can_V_Rx can_v_rx_create (const Can_Lut_Sw * const can_lut_sw , const UInt16 rx_q_size)
{
  CRITICAL ;

  Can_V_Rx can_v_rx    = (Can_V_Rx) os_mem_request (sizeof *can_v_rx) ;

  can_v_rx->obj.init.rx_q_size  = rx_q_size  ;

  can_v_rx->obj.init.can_lut_sw = can_lut_sw ;

  C_ENTER ;
    {
      static Can_V_Rx can_v_rx_last = NULL ;

      if (can_v_vars.init.can_v_rx_list)
        {
          can_v_rx_last->obj.init.next = can_v_rx ;
        }
      else
        {
          can_v_vars.init.can_v_rx_list = can_v_rx ;
        }

      can_v_rx->obj.init.next = NULL ;

      can_v_rx_last  = can_v_rx ;

      can_v_vars.init.can_v_rx_count ++ ;
    }
  C_LEAVE ;

  return can_v_rx ;
}

